import {pricing,validateEconomics} from './economics.js';
import {preset,newSku,styles,plan} from './plan.js';
export function fresh(){const p=newSku();return {version:2,name:'Untitled retail concept',type:'half',catalog:[p],templates:{half:{...preset('half'),slots:Object.fromEntries([0,1,2,3].map(i=>[`${i}:0`,{sku:p.id,qty:null,facings:null}]))}},branding:{header:null,fascia:null,side:null}};}
export function validateProject(raw){
 if(raw?.version===1){const s=raw.state;if(!s)throw Error('Invalid legacy project.');const p={...newSku(),w:s.pw,d:s.pd,h:s.ph,rotate:!!s.rotate,art:raw.art||null,original:raw.art||null};raw={version:2,name:raw.name||'Imported concept',type:s.type,catalog:[p],templates:{[s.type]:{...preset(s.type),...s,color:raw.color,slots:Object.fromEntries(Array.from({length:s.levels},(_,i)=>[`${i}:0`,{sku:p.id,qty:null,facings:null}]))}},branding:{header:null,fascia:null,side:null}};}
 if(!raw||raw.version!==2||!styles[raw.type]||typeof raw.name!=='string'||!Array.isArray(raw.catalog)||raw.catalog.length>24||!raw.templates||!raw.templates[raw.type])throw Error('Unsupported or invalid project.');
 raw.economicsBasis??='first';if(!['first','landed'].includes(raw.economicsBasis))throw Error('Invalid economics cost basis.');
 const id=new Set(),image=x=>x===null||x===undefined||(typeof x==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(x)&&x.length<24*1024*1024);
 for(const p of raw.catalog){p.economics={...pricing(p)};validateEconomics(p);p.cost??=null;if(!(p.cost===null||Number.isFinite(p.cost)&&p.cost>=0))throw Error('Invalid SKU cost.');if(typeof p.id!=='string'||id.has(p.id)||typeof p.sku!=='string'||typeof p.name!=='string'||!['box','cutout','open','bottle','model','reference'].includes(p.representation)||['w','d','h'].some(k=>!Number.isFinite(p[k])||p[k]<=0)||!/^#[a-f0-9]{6}$/i.test(p.color)||!image(p.art)||!image(p.original)||!(p.price===null||Number.isFinite(p.price)&&p.price>=0)||!Number.isInteger(p.stackCount)||p.stackCount<1||p.stackCount>12||typeof p.rotate!=='boolean'||typeof p.stackable!=='boolean')throw Error('Invalid SKU record.');if(p.model&&(typeof p.model!=='string'||!/^data:[^,]*;base64,/.test(p.model)||p.model.length>30*1024*1024))throw Error('Invalid model data.');id.add(p.id);}
 for(const [type,s] of Object.entries(raw.templates)){if(!styles[type]||s.type!==type||!/^#[a-f0-9]{6}$/i.test(s.color)||!s.slots||typeof s.slots!=='object'||!Array.isArray(s.tierHeights)||!Array.isArray(s.tierDepths)||s.tierHeights.length>12||s.tierDepths.length>12||[...s.tierHeights,...s.tierDepths].some(n=>!Number.isFinite(n)))throw Error('Invalid display template.');s.dividerPositions??=[];s.shelfDepths??=[];s.removalClearance??=0;if(!Array.isArray(s.dividerPositions)||!Array.isArray(s.shelfDepths)||s.shelfDepths.length>12||[...s.dividerPositions,...s.shelfDepths].some(n=>!Number.isFinite(n))||!Number.isFinite(s.removalClearance)||s.removalClearance<0)throw Error('Invalid clearances or divider positions.');const r=plan(s,raw.catalog);if(!r.surfaces.length)throw Error(r.issues[0]||'Invalid structure.');for(const slot of Object.values(s.slots))if(slot.sku&&!id.has(slot.sku))throw Error('Project has an unknown SKU assignment.');}
 if(!raw.branding||!Object.values(raw.branding).every(image))throw Error('Invalid branding asset.');
 return raw;
}
